(window.__AC=window.__AC||{});__AC["assets5"]=(__AC["assets5"]||'')+"// Глава V «Сангра»: реплики (Edge TTS, ударения), заставка, арт (Pollinations), музыка (синтез)\nwindow.ASSETS_LINES=window.ASSETS_LINES||{};window.ASSETS_AUDIO=window.ASSETS_AUDIO||{};window.ASSETS_IMG=window.ASSETS_IMG||{};\nObject.assign(window.ASSETS_LINES,{\"l5_a\": {\"s\": \"avram\", \"t\": \"Ирма… слышишь? Сангра глушит связь… Будь осторожна. Гильдия не любит гостей.\"}, \"l5_b\": {\"s\": \"irma\", \"t\": \"Аврам? Аврам! …Пропал. Ладно. Дальше сама.\"}, \"l5_gate\": {\"s\": \"irma\", \"t\": \"Шлюз заперт. Кольцо-рычаг над воротами — дёрну Клювом.\"}, \"l5_lift\": {\"s\": \"irma\", \"t\": \"Грузовой лифт. Закачу на него ящик — и поеду вместе с ним.\"}, \"l5_steam\": {\"s\": \"irma\", \"t\": \"Паровые кварталы. Трубы ещё дышат. Иду в паузах между выбросами.\"}, \"l5_lamp\": {\"s\": \"veil\", \"t\": \"Внимание. В секторе посторонний. Фонари, зачистить квартал.\"}, \"l5_hide\": {\"s\": \"irma\", \"t\": \"Фонари Гильдии. Свет не проходит сквозь железо. Держусь за укрытиями.\"}, \"l5_mara1\": {\"s\": \"mara\", \"t\": \"Стой! Ещё шаг — и тебя подпалит заслонка. Ты кто такая?\"}, \"l5_mara2\": {\"s\": \"irma\", \"t\": \"Ирма. С «Зари». Ищу человека. Его зовут Тео.\"}, \"l5_mara3\": {\"s\": \"mara\", \"t\": \"Тео? Он чинил с нами сердце Хребта. А потом ушёл — и сказал, что ты придёшь. Я Мара. Последний механик Сангры.\"}, \"l5_mara4\": {\"s\": \"mara\", \"t\": \"Город не умер. Его усыпили. Вейл снял три предохранителя — и Хребет встал.\"}, \"l5_mara5\": {\"s\": \"mara\", \"t\": \"Запустим Хребет — и Сангра поедет снова. Помоги мне, и я отдам тебе то, что оставил Тео.\"}, \"l5_sola_m\": {\"s\": \"sola\", \"t\": \"Механик? Здесь? Значит, город ещё живой.\"}, \"l5_light\": {\"s\": \"irma\", \"t\": \"Световой колодец. Встану в столб света — плащ поймает луч.\"}, \"l5_wheel\": {\"s\": \"mara\", \"t\": \"Колесо Хребта! Прыгай на лопасти, пока оно крутится!\"}, \"l5_depot\": {\"s\": \"mara\", \"t\": \"Депо затопило, когда встали насосы. Понтоны тонут под весом — не стой на них долго!\"}, \"l5_fuse\": {\"s\": \"mara\", \"t\": \"Вот они — три предохранителя. Две плиты под грузом и один приёмник света. Зажги все три лампы — и ворота откроются.\"}, \"l5_sola_s\": {\"s\": \"sola\", \"t\": \"Я помню зеркала, Ирма. Свет найдёт дорогу.\"}, \"l5_sola_i\": {\"s\": \"irma\", \"t\": \"Сола бы сейчас пригодилась… Справлюсь сама.\"}, \"l5_purge\": {\"s\": \"veil\", \"t\": \"Несанкционированный запуск. Начинаю продувку сектора. Грузу — сохранять спокойствие.\"}, \"l5_run\": {\"s\": \"mara\", \"t\": \"Он пускает пар по всей линии! Бегом к сердцу, Ирма! Не оглядывайся!\"}, \"l5_end\": {\"s\": \"irma\", \"t\": \"Сердце Хребта. Держись, старик… Сейчас.\"}, \"l5_end2\": {\"s\": \"mara\", \"t\": \"Слышишь? Он дышит! Сангра дышит!\"}, \"l5_teo\": {\"s\": \"mara\", \"t\": \"Это оставил Тео. Карта к Звёздному Залу. Он сказал: «Кольцо — это не путь. Кольцо — это цепь».\"}, \"e5\": {\"s\": \"irma\", \"t\": \"Звёздный Зал. Там всё началось. Там я и закончу.\"}, \"s9\": {\"s\": \"narr\", \"t\": \"Приказ номер сорок. Сангру снять с Кольца. Жителей считать грузом. Подпись — Смотритель Вейл.\"}, \"s10\": {\"s\": \"irma\", \"t\": \"Записка Тео: «Не верь фонарям. Они светят не для нас».\"}, \"l4_tide\": {\"s\": \"irma\", \"t\": \"Тень уходит! Солнечный прилив! Бегом к семафору!\"}, \"l4_sola_end\": {\"s\": \"sola\", \"t\": \"Это знак сумеречного. Он прошёл здесь прошлым летом, к Сангре. Я помню его тень.\"}, \"e4\": {\"s\": \"irma\", \"t\": \"Тео жив. Орсо ждёт. Впереди Сангра и Звёздный Зал. Значит, туда я и иду.\"}, \"l4_sola3\": {\"s\": \"sola\", \"t\": \"Дед говорил: раньше солнце стояло ниже. Оно ползёт быстрее, чем считают Навигаторы. Зеркала это помнят.\"}, \"l4_stay\": {\"s\": \"sola\", \"t\": \"Тогда возьми жар из нашего горна. Твоя Печка полна. И возвращайся.\"}, \"l4_plate\": {\"s\": \"irma\", \"t\": \"Створку держит плита. Моего веса мало — нужен груз.\"}});\nObject.assign(window.ASSETS_AUDIO,{\"m_city\": \"";